report.instrumentation_patch:
diff --git a/graphics/cherenkov/gpu/src/render/mod.rs b/graphics/cherenkov/gpu/src/render/mod.rs
index 716ce5759..2e42fb92c 100644
--- a/graphics/cherenkov/gpu/src/render/mod.rs
+++ b/graphics/cherenkov/gpu/src/render/mod.rs
@@ -5047,6 +5047,17 @@ impl GpuRenderer {
             self.evict_dead_mask_textures();
         }
         result?;
+        if let Some(report) = self.device.generate_allocator_report() {
+            let mut labels = std::collections::BTreeMap::new();
+            for allocation in &report.allocations {
+                let value = labels.entry(allocation.name.as_str()).or_insert((0_u64, 0_u64));
+                value.0 += 1;
+                value.1 += allocation.size;
+            }
+            tracing::debug!(allocated = report.total_allocated_bytes,
+                reserved = report.total_reserved_bytes, engine = self.memory().gpu.0,
+                labels = ?labels, "picture allocator census");
+        }
         diag::set_phase("present");
         let (mut redraw, commits) = self.present_windows(frame)?;
         self.request_redraw(&mut redraw);
@@ -5214,6 +5225,17 @@ impl GpuRenderer {
